  "code": "def merge_intervals(pairs):
    """Merge normalized, sorted intervals that overlap or share an endpoint.

    Args:
        pairs: list of [a, b] integer endpoint pairs. May be unsorted or unnormalized.

    Returns:
        list of [min, max] pairs sorted and merged; [] if input empty.
    """
    normalized = []
    for a, b in pairs:
        if a <= b:
            normalized.append((a, b))
        else:
            normalized.append((b, a))
    if not normalized:
        return []
    normalized.sort(key=lambda x: x[0])
    merged = [list(normalized[0])]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged"
